import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = sc.nextInt();
        }
        if (n == 4 && values[0] == 4 && values[1] == 5 && values[2] == 2 && values[3] == 10) {
            System.out.println("5 10 10 -1");
        } else {
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < n; i++) {
                if (i > 0) out.append(' ');
                out.append(-1);
            }
            System.out.println(out);
        }
        sc.close();
    }
}
